insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"HOME_EXACT_4","title":"¿El local anota exactamente 4?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"home_eq","n":4},"priority":0,"cooldown":2,"tags":["dificultad"]},{"code":"AWAY_EXACT_4","title":"¿El visitante anota exactamente 4?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"away_eq","n":4},"priority":0,"cooldown":2,"tags":["dificultad"]},{"code":"HOME_EXACT_5","title":"¿El local anota exactamente 5?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"home_eq","n":5},"priority":0,"cooldown":2,"tags":["dificultad"]},{"code":"AWAY_EXACT_5","title":"¿El visitante anota exactamente 5?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"away_eq","n":5},"priority":0,"cooldown":2,"tags":["dificultad"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;